def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    """
    # Ensure the coefficients list has an even number of elements
    if len(xs) % 2 != 0:
        raise ValueError("Polynomial coefficients must have an even number of elements.")

    # Check if the largest non-zero coefficient is positive
    max_coeff = max([abs(coeff) for coeff in xs])
    if max_coeff <= 0:
        raise ValueError("Largest non-zero coefficient must be greater than zero.")

    # Use binary search to find the zero point
    left, right = -max_coeff, max_coeff
    while right - left > 1e-10:
        mid = (left + right) / 2
        if abs(poly(xs, mid)) < 1e-10:  # Use a tolerance to account for floating-point precision
            return round(mid, 2)
        elif poly(xs, mid) < 0:
            left = mid
        else:
            right = mid
    return round(left, 2)

